package fr.formation.modular.reservation;
import fr.formation.modular.notification.NotificationFacade; import fr.formation.modular.room.RoomFacade; import fr.formation.modular.shared.*; import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.*; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service class ReservationModule {
 private final ReservationJpaRepository repository; private final RoomFacade rooms; private final NotificationFacade notifications;
 ReservationModule(ReservationJpaRepository repository,RoomFacade rooms,NotificationFacade notifications){this.repository=repository;this.rooms=rooms;this.notifications=notifications;}
 @Transactional ReservationView create(UUID roomId,String email,int participants,LocalDateTime startsAt,LocalDateTime endsAt){var room=rooms.require(roomId);if(email==null||email.isBlank()||participants<1||startsAt==null||endsAt==null||!startsAt.isBefore(endsAt))throw new BusinessException("Invalid reservation");if(participants>room.capacity())throw new BusinessException("Room capacity exceeded");if(repository.hasOverlap(roomId,endsAt,startsAt))throw new BusinessException("Room unavailable");var saved=repository.save(new ReservationRecord(UUID.randomUUID(),roomId,email,participants,startsAt,endsAt));notifications.reservationConfirmed(email);return view(saved);}
 ReservationView get(UUID id){return repository.findById(id).map(this::view).orElseThrow(()->new NotFoundException("Reservation not found"));}
 @Transactional void cancel(UUID id){var record=repository.findById(id).orElseThrow(()->new NotFoundException("Reservation not found"));record.status=Status.CANCELLED;}
 private ReservationView view(ReservationRecord r){return new ReservationView(r.id,r.roomId,r.organizerEmail,r.participants,r.startsAt,r.endsAt,r.status.name());}
 record ReservationView(UUID id,UUID roomId,String organizerEmail,int participants,LocalDateTime startsAt,LocalDateTime endsAt,String status){}
}
interface ReservationJpaRepository extends JpaRepository<ReservationRecord,UUID>{ boolean existsByRoomIdAndStatusAndStartsAtLessThanAndEndsAtGreaterThan(UUID roomId,Status status,LocalDateTime endsAt,LocalDateTime startsAt); default boolean hasOverlap(UUID roomId,LocalDateTime endsAt,LocalDateTime startsAt){return existsByRoomIdAndStatusAndStartsAtLessThanAndEndsAtGreaterThan(roomId,Status.CONFIRMED,endsAt,startsAt);} }
enum Status { CONFIRMED,CANCELLED }
@Entity @Table(name="reservations") class ReservationRecord { @Id UUID id; UUID roomId; String organizerEmail; int participants; LocalDateTime startsAt; LocalDateTime endsAt; @Enumerated(EnumType.STRING) Status status; protected ReservationRecord(){} ReservationRecord(UUID id,UUID roomId,String email,int participants,LocalDateTime startsAt,LocalDateTime endsAt){this.id=id;this.roomId=roomId;this.organizerEmail=email;this.participants=participants;this.startsAt=startsAt;this.endsAt=endsAt;this.status=Status.CONFIRMED;} }
